// Writes src/fixtures/*.generated.ts. Run: pnpm --filter @loadstate/core fixtures:generate
import { writeFileSync } from "node:fs";
import type { FixtureManifest, PackData } from "../src/contracts.ts";
import { generateEdgePack } from "./edge-fixtures.ts";
import { generateCorePack } from "./fixtures.ts";

function write(file: string, pack: { manifest: FixtureManifest; data: PackData }) {
  const lines = [
    "// Generated by packages/core/scripts/generate-fixtures.ts. Do not edit by hand:",
    "// run `pnpm --filter @loadstate/core fixtures:generate` and review the diff.",
    'import type { FixtureManifest, PackData } from "../contracts.js";',
    "",
    `export const manifest: FixtureManifest = ${JSON.stringify(pack.manifest, null, 2)};`,
    "",
    "export const data: PackData = {",
    ...Object.entries(pack.data).flatMap(([name, records]: [string, unknown[]]) => [
      `  ${name}: [`,
      ...records.map((record) => `    ${JSON.stringify(record)},`),
      "  ],",
    ]),
    "};",
    "",
  ];
  const target = new URL(`../src/fixtures/${file}`, import.meta.url);
  writeFileSync(target, lines.join("\n"));
  console.log(`Wrote ${pack.manifest.id} (${pack.manifest.checksum}) to ${target.pathname}`);
}

write("core-1.generated.ts", generateCorePack());
write("edge-1.generated.ts", generateEdgePack());
